const HERB_REGIONS = {"med": {"jp": "地中海・ヨーロッパ", "en": "MEDITERRANEAN & EUROPE", "desc": "乾いた夏と温暖な冬の地中海沿岸は、ローズマリーやタイム、オレガノなど香りの強いハーブの故郷。古代ギリシャ・ローマの時代から料理や薬に使われてきた。", "pick": "地中海・ヨーロッパ"}, "mideast": {"jp": "中東・北アフリカ", "en": "MIDDLE EAST", "desc": "古代エジプトやペルシャの時代から香料が交易された地域。サフランやクミン、コリアンダーなど、世界中に広まったスパイスの故郷が多い。", "pick": "中東・北アフリカ"}, "india": {"jp": "インド・スリランカ", "en": "INDIA & SRI LANKA", "desc": "「スパイスの国」インド。胡椒、カルダモン、ターメリックなど多くのスパイスの原産地で、アーユルヴェーダという伝統医学でも使われてきた。スリランカはシナモンの故郷。", "pick": "インド・スリランカ"}, "seasia": {"jp": "東南アジア", "en": "SOUTHEAST ASIA", "desc": "レモングラスやガランガルなど、さわやかな香りのハーブを生のまま使う料理が多い。インドネシアのモルッカ諸島は、クローブとナツメグの原産地で「香料諸島」と呼ばれた。", "pick": "東南アジア"}, "china": {"jp": "中国・東アジア", "en": "CHINA & EAST ASIA", "desc": "「医食同源（薬食同源）」の考えのもと、食材と生薬の境目がゆるやかな地域。薬膳料理や漢方薬の材料となる生薬の多くが、中国や朝鮮半島で採れる。", "pick": "中国・東アジア"}, "japan": {"jp": "日本", "en": "JAPAN", "desc": "山椒、わさび、しそ、みょうがなど、香りを添える「薬味」の文化。料理の脇役として、季節感と香りを大切にしてきた。", "pick": "日本"}, "americas": {"jp": "中南米", "en": "LATIN AMERICA", "desc": "唐辛子、バニラ、オールスパイスの原産地。コロンブス以降、ヨーロッパやアジアへ広まり、世界中の料理を変えた。", "pick": "中南米"}, "kampo": {"jp": "漢方処方", "en": "KAMPO", "desc": "生薬を組み合わせた漢方薬。日本では、医師が処方する医療用のほか、薬局やドラッグストアで買える一般用の漢方薬もある。", "pick": "漢方処方"}};
