const HERB_TYPES = [{"id": "herb", "name": "ハーブ", "en": "Herb", "kind": "香りを楽しむ", "home": "地中海、ヨーロッパ、東南アジア、日本", "p": [4, 0, 1, 1, 0, 3, 1, 4], "tags": ["葉", "爽やか", "生でも乾燥でも"], "desc": "香りのよい草の葉や花。料理の香りづけのほか、ハーブティーとしても楽しまれる。生のもの（フレッシュ）は香りが鮮やかで、乾燥したもの（ドライ）は香りが凝縮して長く保存できる。"}, {"id": "spice", "name": "スパイス", "en": "Spice", "kind": "香りを楽しむ", "home": "インド、スリランカ、東南アジア、中南米", "p": [5, 3, 2, 1, 0, 1, 3, 2], "tags": ["種", "樹皮", "根", "実"], "desc": "植物の種や実、樹皮、根、つぼみなどを乾燥させた香辛料。香りづけ、辛みづけ、色づけの3つの役割がある。粒（ホール）のまま使うか、粉（パウダー）にして使う。"}, {"id": "blend", "name": "ミックススパイス", "en": "Spice Blend", "kind": "香りを楽しむ", "home": "インド、中国、日本、フランス", "p": [5, 3, 1, 1, 0, 1, 3, 3], "tags": ["ブレンド", "国ごとの味"], "desc": "いくつものスパイスやハーブを合わせたもの。インドのガラムマサラ、中国の五香粉、日本の七味唐辛子など、それぞれの国の料理の味を決める。"}, {"id": "shoyaku", "name": "生薬・薬膳食材", "en": "Crude Drug & Yakuzen", "kind": "薬膳・漢方", "home": "中国、日本、韓国", "p": [2, 1, 2, 3, 1, 0, 4, 1], "tags": ["薬膳", "漢方の材料", "性と味"], "desc": "植物の根や皮、実などを乾燥させた、漢方薬の材料（生薬）や、薬膳料理に使われる食材。薬膳では、食材を体を温めるか冷やすか（五性：熱・温・平・涼・寒）と、味（五味：酸・苦・甘・辛・鹹）で分類する。"}, {"id": "kampo", "name": "漢方処方", "en": "Kampo Formula", "kind": "薬膳・漢方", "home": "日本（中国の古典がもと）", "p": [1, 1, 2, 2, 0, 0, 4, 0], "tags": ["医薬品", "生薬の組み合わせ", "体質（証）"], "desc": "複数の生薬を決まった割合で組み合わせた薬。古代中国の医学書をもとに、日本で独自に発展した「漢方」で用いられる。同じ症状でも、体質（証）によって合う処方が異なる。"}];
